import {coverDesigns,coverOptions,coverFonts,coverDirection,coverFont} from './cover-designs.js';
import {bookCoverSVG,coverPalettes,localeOf} from './book.js';
import {esc} from './text.js';
export function coverFormValues(form,p){const raw=Object.fromEntries(new FormData(form)),next={...p};for(const key of ['title','subtitle','author','blurb','imprintName'])if(key in raw)next[key]=raw[key];const options={...coverOptions(p)};for(const [key,value]of Object.entries(raw))if(key.startsWith('cover.'))options[key.slice(6)]=value;next.coverOptions=coverOptions({...p,coverOptions:options});return next;}
export function coverGallery(p,filter='All',query=''){return coverDesigns.filter(d=>(filter==='All'||d.category===filter)&&(!query||(d.name+' '+d.category).toLowerCase().includes(query.toLowerCase()))).map(d=>{const thumb={...p,coverDesign:d.id,color:d.palette,coverOptions:{},image:p.image||null};return `<button type="button" class="cover-choice ${coverDirection(p.coverDesign).id===d.id?'selected':''}" data-action="choose-cover-design" data-id="${d.id}" aria-pressed="${coverDirection(p.coverDesign).id===d.id}"><span class="cover-thumb">${bookCoverSVG(thumb)}</span><strong>${d.name}</strong><small>${d.category}</small></button>`;}).join('');}
const choices=(arr,current)=>arr.map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(v)}</option>`).join('');
export function coverValue(key,value){return ['titleScale','artScale','texture','imageOverlay'].includes(key)?Math.round(value*100)+'%':key==='artRotation'?value+'°':String(value);}
export function coverControls(p,B){const fixedFace=({ar:'Noto Naskh Arabic',ur:'Noto Naskh Arabic',hi:'Noto Serif Devanagari',bn:'Noto Serif Bengali'})[localeOf(p).code],o=coverOptions(p),base=coverPalettes[p.color]||coverPalettes.sea,range=(name,label,min,max,step)=>`<label class="field cover-range"><span>${label}<output data-cover-output="${name}">${coverValue(name,o[name])}</output></span><input type="range" name="cover.${name}" min="${min}" max="${max}" step="${step}" value="${o[name]}"></label>`;return `<div class="cover-edit-tabs" role="group" aria-label="Cover controls">${B('cover-undo','Undo','clock','quiet','type="button"')}${B('reset-cover-style','Reset style','settings','quiet','type="button"')}</div><details class="cover-controls" open><summary>Type & composition</summary><div class="form-grid">${fixedFace?`<div class="field"><span>Language typeface</span><p class="small">${fixedFace}</p><small>Matched to your book’s language.</small></div>`:`<label class="field"><span>Typeface</span><select name="cover.font">${choices(Object.keys(coverFonts),o.font)}</select></label>`}<label class="field"><span>Alignment</span><select name="cover.align">${choices(['left','center','right'],o.align)}</select></label><label class="field"><span>Title position</span><select name="cover.titlePosition">${choices(['upper','middle','lower'],o.titlePosition)}</select></label><label class="field"><span>Border</span><select name="cover.border">${choices(['none','single','double'],o.border)}</select></label></div>${range('titleScale','Title size',.65,1.4,.05)}</details><details class="cover-controls"><summary>Color & artwork</summary><div class="cover-colors">${[['bg','Paper'],['ink','Type'],['art','Artwork']].map(([key,label])=>`<label><input type="color" name="cover.${key}" value="${o[key]||base[key]}"><span>${label}</span></label>`).join('')}</div>${range('artScale','Artwork size',.5,1.6,.05)}${range('artRotation','Rotation',-180,180,5)}${['Orbit','Lines','Ginkgo','Fern','Arch','Contour','Dune','Tide','Rain','Solstice','Meridian','Tessera','Ripple','Labyrinth','Halftone','Loom'].includes(coverDirection(p.coverDesign).id)?range('density','Pattern detail',4,24,1):''}${range('stroke','Line weight',1,12,1)}${range('texture','Paper texture',0,.3,.02)}${p.image?range('imageOverlay','Image tint',0,.9,.05):''}</details>`;}
const fonts=new Map();
export async function exportCoverSVG(p,back=false){const font=coverFont(p,localeOf(p).code);let promise=fonts.get(font.file);if(!promise){promise=(async()=>{const response=await fetch(new URL('assets/'+font.file,import.meta.url));if(!response.ok)throw Error('The cover typeface could not be read. Try the export again.');const bytes=new Uint8Array(await response.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const licenseFile=({'lora.ttf':'Lora','dm-sans.ttf':'DM-Sans','literata.ttf':'literata','source-serif.ttf':'source-serif','ibm-plex.ttf':'ibm-plex','book-arabic.ttf':'book-arabic','book-devanagari.ttf':'book-devanagari','book-bengali.ttf':'book-bengali'})[font.file];const license=await fetch(new URL('licenses/'+licenseFile+'-OFL.txt',import.meta.url));if(!license.ok)throw Error('The cover font license could not be read. Try the export again.');return {base64:btoa(binary),license:await license.text()};})();fonts.set(font.file,promise);promise.catch(()=>fonts.delete(font.file));}const data=await promise;return bookCoverSVG(p,back).replace(/(<svg[^>]*>)/,`$1<metadata>${esc(data.license)}</metadata><style>@font-face{font-family:'${font.family}';src:url(data:font/ttf;base64,${data.base64})}text{font-family:'${font.family}'}</style>`);}

export function coverPaletteSelected(p,id){const o=coverOptions(p),base=coverPalettes[p.color]||coverPalettes.sea,target=coverPalettes[id];return !!target&&['bg','ink','art'].every(key=>(o[key]||base[key]).toLowerCase()===target[key].toLowerCase());}
